// Project configuration (template). Each section is a separate named export.

// Fonts
export const fonts = {
	// Source fonts folder (.ttf, .otf, .woff)
	src: 'assets/fonts/src',
	// Folder for converted .woff2 files (may be the same as src)
	dest: 'assets/fonts',
	// Styles file generated by the script
	css: 'assets/css/fonts.css',
	// url() prefix in CSS; empty = computed automatically (relative path from css to dest)
	cssUrl: '',
	// Convert source fonts to woff2
	convert: true,
	// Generate the @font-face styles file
	generateCss: true,
	// Preload tags (generated fragment file)
	preload: {
		// Generate the preload fragment
		enable: true,
		// 'all' or font file names without .woff2 extension (case-insensitive)
		files: ['Roboto-Variable', 'Sk-Modernist-Regular'],
		// Fragment file to write
		out: 'partials/fonts-preload.html',
		// Template file for the output; empty = plain html tags.
		// Short name = bundled template: 'html', 'astro', 'jsx' (tools/fonts/templates/preload.<name>.tpl),
		// or a path to a custom file: 'tools/fonts/templates/preload.custom.tpl'.
		// Template supports {{#tags}}...{{/tags}} block with variables: {{url}} {{file}} {{name}} {{var}} {{path}}
		template: '',
		// Base url for href; empty = '/' + dest
		url: '',
	},
	// Keep source files after conversion
	keepSource: true,
	// Clean font files in dest before conversion (dest mirrors src)
	cleanDest: true,
	// font-display value in @font-face
	fontDisplay: 'swap',
}
